  ('e2000000-0000-4000-a000-000000000ff3', 'CO-MAT-00788', 3, 6, 'medio', 2, 62, 2026, 'multiple_choice', 'Juros simples', 'Diego aplicou R$ 1.400,00 a juros simples de 2% ao mês, durante 8 meses. Qual foi o valor dos juros recebidos no período?', 'Juros simples: J = C × i × t = R$ 1.400,00 × 0,02 × 8 = R$ 224,00. O montante seria R$ 1.624,00, mas a pergunta pede só os juros.', 'J = C · i · t, com a taxa em forma decimal.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000000ff4', 'CO-MAT-00789', 3, 6, 'medio', 2, 62, 2026, 'multiple_choice', 'Juros simples', 'Felipe aplicou R$ 1.300,00 a juros simples de 1% ao mês, durante 6 meses. Qual foi o valor dos juros recebidos no período?', 'Juros simples: J = C × i × t = R$ 1.300,00 × 0,01 × 6 = R$ 78,00. O montante seria R$ 1.378,00, mas a pergunta pede só os juros.', 'J = C · i · t, com a taxa em forma decimal.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
