  ('e2000000-0000-4000-a000-000000001044', 'CO-FIS-00009', 6, 22, 'medio', 2, 62, 2026, 'multiple_choice', 'Leis de Newton', 'Um corpo de massa 1.000 kg recebe uma força resultante que lhe dá aceleração de 0,5 m/s². Pela segunda lei de Newton, qual é a intensidade dessa força?', 'F = m · a = 1.000 × 0,5 = 500 N.', 'Segunda lei: força resultante = massa × aceleração.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001045', 'CO-FIS-00010', 6, 22, 'medio', 2, 62, 2026, 'multiple_choice', 'Leis de Newton', 'Um corpo de massa 1.000 kg recebe uma força resultante que lhe dá aceleração de 3 m/s². Pela segunda lei de Newton, qual é a intensidade dessa força?', 'F = m · a = 1.000 × 3 = 3.000 N.', 'Segunda lei: força resultante = massa × aceleração.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
