  ('e2000000-0000-4000-a000-00000000104a', 'CO-FIS-00015', 6, 22, 'medio', 2, 62, 2026, 'multiple_choice', 'Leis de Newton', 'Um corpo de massa 800 kg recebe uma força resultante que lhe dá aceleração de 2 m/s². Pela segunda lei de Newton, qual é a intensidade dessa força?', 'F = m · a = 800 × 2 = 1.600 N.', 'Segunda lei: força resultante = massa × aceleração.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000104b', 'CO-FIS-00016', 6, 121, 'enem', 3, 62, 2026, 'multiple_choice', 'Consumo de energia elétrica', 'Em uma casa, um chuveiro elétrico de 5.500 W fica ligado 0,5 h por dia, durante 30 dias. Se o kWh custa R$ 0,60, qual é o custo mensal desse aparelho?', 'Energia = P × t = 5,5 kW × 15 h = 82,5 kWh. Custo = 82,5 × R$ 0,60 = R$ 49,50.', 'Passe a potência para kW e multiplique pelas horas do mês; depois pela tarifa.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000104c', 'CO-FIS-00017', 6, 121, 'enem', 3, 62, 2026, 'multiple_choice', 'Consumo de energia elétrica', 'Em uma casa, uma lâmpada de LED de 10 W fica ligado 0,5 h por dia, durante 30 dias. Se o kWh custa R$ 0,60, qual é o custo mensal desse aparelho?', 'Energia = P × t = 0,01 kW × 15 h = 0,15 kWh. Custo = 0,15 × R$ 0,60 = R$ 0,09.', 'Passe a potência para kW e multiplique pelas horas do mês; depois pela tarifa.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
