  ('e2000000-0000-4000-a000-000000001055', 'CO-QUI-00001', 7, 131, 'enem', 2, 62, 2026, 'multiple_choice', 'Concentração comum', 'Para preparar uma salmoura, dissolvem-se 2 g de soluto em água até completar 0,5 L de solução. Qual a concentração comum obtida?', 'C = m ÷ V = 2 g ÷ 0,5 L = 4 g/L.', 'Concentração comum = massa do soluto ÷ volume da solução em litros.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001056', 'CO-QUI-00002', 7, 131, 'enem', 2, 62, 2026, 'multiple_choice', 'Concentração comum', 'Para preparar uma solução de açúcar, dissolvem-se 10 g de soluto em água até completar 5 L de solução. Qual a concentração comum obtida?', 'C = m ÷ V = 10 g ÷ 5 L = 2 g/L.', 'Concentração comum = massa do soluto ÷ volume da solução em litros.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
