  ('e2000000-0000-4000-a000-000000001079', 'CO-MAT-00882', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 8 e razão 2. Qual é a soma dos 4 primeiros termos?', 'Sₙ = a₁(qⁿ − 1)/(q − 1) = 8·(2⁴ − 1)/(2 − 1) = 120.', 'Use Sₙ = a₁(qⁿ − 1)/(q − 1).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000107a', 'CO-MAT-00883', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 4 e razão 4. Qual é o 5º termo?', 'aₙ = a₁·qⁿ⁻¹ = 4·4⁴ = 1.024.', 'Na PG, cada termo é o anterior vezes a razão: aₙ = a₁·qⁿ⁻¹.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000107b', 'CO-MAT-00884', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 9 e razão 5. Qual é a soma dos 4 primeiros termos?', 'Sₙ = a₁(qⁿ − 1)/(q − 1) = 9·(5⁴ − 1)/(5 − 1) = 1.404.', 'Use Sₙ = a₁(qⁿ − 1)/(q − 1).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
