  ('e2000000-0000-4000-a000-00000000107f', 'CO-MAT-00888', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 2 e razão 4. Qual é a soma dos 4 primeiros termos?', 'Sₙ = a₁(qⁿ − 1)/(q − 1) = 2·(4⁴ − 1)/(4 − 1) = 170.', 'Use Sₙ = a₁(qⁿ − 1)/(q − 1).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001080', 'CO-MAT-00889', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 1 e razão 5. Qual é a soma dos 4 primeiros termos?', 'Sₙ = a₁(qⁿ − 1)/(q − 1) = 1·(5⁴ − 1)/(5 − 1) = 156.', 'Use Sₙ = a₁(qⁿ − 1)/(q − 1).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001081', 'CO-MAT-00890', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 5 e razão 3. Qual é a soma dos 7 primeiros termos?', 'Sₙ = a₁(qⁿ − 1)/(q − 1) = 5·(3⁷ − 1)/(3 − 1) = 5.465.', 'Use Sₙ = a₁(qⁿ − 1)/(q − 1).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
