  ('e2000000-0000-4000-a000-000000001083', 'CO-MAT-00892', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 6 e razão 2. Qual é o 4º termo?', 'aₙ = a₁·qⁿ⁻¹ = 6·2³ = 48.', 'Na PG, cada termo é o anterior vezes a razão: aₙ = a₁·qⁿ⁻¹.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001084', 'CO-MAT-00893', 3, 143, 'medio', 3, 62, 2026, 'multiple_choice', 'Progressão geométrica', 'Uma progressão geométrica tem primeiro termo 5 e razão 2. Qual é o 6º termo?', 'aₙ = a₁·qⁿ⁻¹ = 5·2⁵ = 160.', 'Na PG, cada termo é o anterior vezes a razão: aₙ = a₁·qⁿ⁻¹.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001085', 'CO-MAT-00894', 3, 110, 'enem', 3, 62, 2026, 'multiple_choice', 'Progressão aritmética', 'Um ciclista fez 20 páginas lidas no 1º dia e, a cada dia, aumentou 10 páginas em relação ao dia anterior. Qual foi o total acumulado nos 20 primeiros dias?', 'É uma PA: a₁ = 20, r = 10. a20 = 20 + 19·10 = 210. Soma: (a₁ + aₙ)·n/2 = (20 + 210)·20/2 = 2.300.', 'Ache o último termo e use Sₙ = (a₁ + aₙ)·n/2.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001086', 'CO-MAT-00895', 3, 110, 'enem', 3, 62, 2026, 'multiple_choice', 'Progressão aritmética', 'Um ciclista fez 54 quilômetros pedalados no 1º dia e, a cada dia, aumentou 8 km em relação ao dia anterior. Qual foi o total acumulado nos 15 primeiros dias?', 'É uma PA: a₁ = 54, r = 8. a15 = 54 + 14·8 = 166. Soma: (a₁ + aₙ)·n/2 = (54 + 166)·15/2 = 1.650.', 'Ache o último termo e use Sₙ = (a₁ + aₙ)·n/2.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001087', 'CO-MAT-00896', 3, 110, 'enem', 3, 62, 2026, 'multiple_choice', 'Progressão aritmética', 'Um ciclista fez 33 minutos de treino no 1º dia e, a cada dia, aumentou 15 minutos em relação ao dia anterior. Qual foi o total acumulado nos 26 primeiros dias?', 'É uma PA: a₁ = 33, r = 15. a26 = 33 + 25·15 = 408. Soma: (a₁ + aₙ)·n/2 = (33 + 408)·26/2 = 5.733.', 'Ache o último termo e use Sₙ = (a₁ + aₙ)·n/2.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001088', 'CO-MAT-00897', 3, 110, 'enem', 3, 62, 2026, 'multiple_choice', 'Progressão aritmética', 'Uma estudante fez 12 minutos de treino no 1º dia e, a cada dia, aumentou 9 minutos em relação ao dia anterior. Qual foi o total acumulado nos 13 primeiros dias?', 'É uma PA: a₁ = 12, r = 9. a13 = 12 + 12·9 = 120. Soma: (a₁ + aₙ)·n/2 = (12 + 120)·13/2 = 858.', 'Ache o último termo e use Sₙ = (a₁ + aₙ)·n/2.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
