  ('e2000000-0000-4000-a000-0000000010b1', 'CO-MAT-00938', 3, 149, 'medio', 4, 62, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (2 − i)·(3 + 3i) é igual a:', 'Aplicando a distributiva: 2·3 + 2·3i + (−1)·3i + (−1)·3i². Como i² = −1, a parte real é 6 + 3 = 9 e a parte imaginária é 3i. Resultado: 9 + 3i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010b2', 'CO-MAT-00939', 3, 149, 'medio', 4, 62, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−4 + 4i)·(6 − i) é igual a:', 'Aplicando a distributiva: (−4)·6 + (−4)·(−1)i + 4·6i + 4·(−1)i². Como i² = −1, a parte real é −24 + 4 = −20 e a parte imaginária é 28i. Resultado: −20 + 28i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010b3', 'CO-MAT-00940', 3, 149, 'medio', 4, 62, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (2 − 2i)·(−1 − 6i) é igual a:', 'Aplicando a distributiva: 2·(−1) + 2·(−6)i + (−2)·(−1)i + (−2)·(−6)i². Como i² = −1, a parte real é −2 − 12 = −14 e a parte imaginária é −10i. Resultado: −14 − 10i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
