  ('e2000000-0000-4000-a000-0000000010ca', 'CO-MAT-00963', 3, 152, 'medio', 3, 62, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(−2, −3) e B(3, −15)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(5² + 12²) = √169 = 13.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010cb', 'CO-MAT-00964', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−4, 4) e (0, −4)?', 'Coeficiente angular: m = (−4 − 4)/(0 − −4) = −2. Substituindo (−4, 4) em y = −2x + n: n = −4. Logo, y = −2x − 4.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010cc', 'CO-MAT-00965', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (3, 18) e (4, 21)?', 'Coeficiente angular: m = (21 − 18)/(4 − 3) = 3. Substituindo (3, 18) em y = 3x + n: n = 9. Logo, y = 3x + 9.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010cd', 'CO-MAT-00966', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (3, −10) e (4, −12)?', 'Coeficiente angular: m = (−12 − −10)/(4 − 3) = −2. Substituindo (3, −10) em y = −2x + n: n = −4. Logo, y = −2x − 4.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010ce', 'CO-MAT-00967', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (3, 7) e (6, 13)?', 'Coeficiente angular: m = (13 − 7)/(6 − 3) = 2. Substituindo (3, 7) em y = 2x + n: n = 1. Logo, y = 2x + 1.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010cf', 'CO-MAT-00968', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−2, −3) e (0, 3)?', 'Coeficiente angular: m = (3 − −3)/(0 − −2) = 3. Substituindo (−2, −3) em y = 3x + n: n = 3. Logo, y = 3x + 3.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d0', 'CO-MAT-00969', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (0, −8) e (4, −16)?', 'Coeficiente angular: m = (−16 − −8)/(4 − 0) = −2. Substituindo (0, −8) em y = −2x + n: n = −8. Logo, y = −2x − 8.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d1', 'CO-MAT-00970', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (1, 1) e (3, 11)?', 'Coeficiente angular: m = (11 − 1)/(3 − 1) = 5. Substituindo (1, 1) em y = 5x + n: n = −4. Logo, y = 5x − 4.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d2', 'CO-MAT-00971', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−4, 18) e (0, 6)?', 'Coeficiente angular: m = (6 − 18)/(0 − −4) = −3. Substituindo (−4, 18) em y = −3x + n: n = 6. Logo, y = −3x + 6.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d3', 'CO-MAT-00972', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (2, 14) e (4, 22)?', 'Coeficiente angular: m = (22 − 14)/(4 − 2) = 4. Substituindo (2, 14) em y = 4x + n: n = 6. Logo, y = 4x + 6.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d4', 'CO-MAT-00973', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (0, 4) e (4, 24)?', 'Coeficiente angular: m = (24 − 4)/(4 − 0) = 5. Substituindo (0, 4) em y = 5x + n: n = 4. Logo, y = 5x + 4.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d5', 'CO-MAT-00974', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−4, 0) e (−2, 4)?', 'Coeficiente angular: m = (4 − 0)/(−2 − −4) = 2. Substituindo (−4, 0) em y = 2x + n: n = 8. Logo, y = 2x + 8.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d6', 'CO-MAT-00975', 3, 153, 'medio', 3, 62, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (3, −5) e (6, −2)?', 'Coeficiente angular: m = (−2 − −5)/(6 − 3) = 1. Substituindo (3, −5) em y = 1x + n: n = −8. Logo, y = x − 8.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d7', 'CO-MAT-00976', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma praça circular tem raio de 31 m. Usando π = 3,14, qual é a sua área?', 'A = π·r² = 3,14·31² = 3.017,54 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d8', 'CO-MAT-00977', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pizza tem raio de 34 m. Usando π = 3,14, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3,14·34 = 213,52 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010d9', 'CO-MAT-00978', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pista circular tem raio de 34 m. Usando π = 3,14, qual é a sua área?', 'A = π·r² = 3,14·34² = 3.629,84 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010da', 'CO-MAT-00979', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma mesa redonda tem raio de 16 m. Usando π = 3, qual é a sua área?', 'A = π·r² = 3·16² = 768 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
