  ('e2000000-0000-4000-a000-0000000010de', 'CO-MAT-00983', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma mesa redonda tem raio de 20 m. Usando π = 3,14, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3,14·20 = 125,6 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010df', 'CO-MAT-00984', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pista circular tem raio de 26 m. Usando π = 3, qual é a sua área?', 'A = π·r² = 3·26² = 2.028 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e0', 'CO-MAT-00985', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Um canteiro circular tem raio de 31 m. Usando π = 3, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3·31 = 186 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
