  ('e2000000-0000-4000-a000-0000000010e2', 'CO-MAT-00987', 3, 154, 'enem', 2, 62, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma mesa redonda tem raio de 15 m. Usando π = 3, qual é a sua área?', 'A = π·r² = 3·15² = 675 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e3', 'CO-MAT-00988', 3, 156, 'enem', 3, 62, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Um cabo esticado do alto de uma torre ao chão tem 56 m de comprimento e forma um ângulo de 30° com o chão. Usando sen 30° ≈ 0,5 e cos 30° ≈ 0,85, a altura da torre é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 30° = 56 × 0,5 = 28 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e4', 'CO-MAT-00989', 3, 156, 'enem', 3, 62, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Um cabo esticado do alto de uma torre ao chão tem 42 m de comprimento e forma um ângulo de 45° com o chão. Usando sen 45° ≈ 0,7 e cos 45° ≈ 0,7, a altura da torre é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 45° = 42 × 0,7 = 29,4 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e5', 'CO-MAT-00990', 3, 156, 'enem', 3, 62, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma escada apoiada num muro tem 20 m de comprimento e forma um ângulo de 60° com o chão. Usando sen 60° ≈ 0,85 e cos 60° ≈ 0,5, a altura que o topo da escada alcança é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 60° = 20 × 0,85 = 17 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e6', 'CO-MAT-00991', 3, 156, 'enem', 3, 62, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma rampa tem 34 m de comprimento e forma um ângulo de 45° com o chão. Usando sen 45° ≈ 0,7 e cos 45° ≈ 0,7, a altura que ela vence é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 45° = 34 × 0,7 = 23,8 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000010e7', 'CO-MAT-00992', 3, 156, 'enem', 3, 62, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma escada apoiada num muro tem 36 m de comprimento e forma um ângulo de 60° com o chão. Usando sen 60° ≈ 0,85 e cos 60° ≈ 0,5, a altura que o topo da escada alcança é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 60° = 36 × 0,85 = 30,6 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
