  ('e2000000-0000-4000-a000-000000001121', 'CO-MAT-01050', 3, 163, 'medio', 5, 62, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação 3x³ − 6x² − 9 = 0. Qual é a produto das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = 3, b = -6, c = 0, d = -9, então a produto é 3.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001122', 'CO-MAT-01051', 3, 163, 'medio', 5, 62, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação 5x³ + 7x² + x − 10 = 0. Qual é a soma dos produtos dois a dois das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = 5, b = 7, c = 1, d = -10, então a soma dos produtos dois a dois é 1/5.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
