  ('e2000000-0000-4000-a000-000000001151', 'CO-MAT-01098', 3, 167, 'medio', 3, 62, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = x − 5 e g(x) = −2x + 2, o valor de f(g(−3)) é:', 'Primeiro g(−3) = 8. Depois f(8) = 3.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001152', 'CO-MAT-01099', 3, 167, 'medio', 3, 62, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = 5x − 8 e g(x) = 2x + 2, o valor de f(g(−1)) é:', 'Primeiro g(−1) = 0. Depois f(0) = −8.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001153', 'CO-MAT-01100', 3, 167, 'medio', 3, 62, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 5x + 8, qual é o valor de f⁻¹(28)?', 'f⁻¹(28) é o x tal que f(x) = 28: 5x  + 8 = 28 ⇒ x = 4.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
